SELECT COUNT(*) newMarks FROM owner_clients WHERE utc_date='2026-10-26' AND marked_at>='2026-10-26 03:00:00';
SELECT p.path, p.collection_version collectionVersion,p.referrer_state referrerState,p.internal_referrer_path internalReferrerPath,COUNT(*) views,SUM(CASE WHEN p.is_owner=0 AND o.daily_client_id IS NULL THEN 1 ELSE 0 END) publiclyEligible FROM page_observations p JOIN owner_clients o ON o.daily_client_id=p.daily_client_id WHERE p.observed_at>='2026-10-26 03:00:00' AND o.utc_date='2026-10-26' AND o.marked_at>='2026-10-26 03:00:00' GROUP BY p.path,p.collection_version,p.referrer_state,p.internal_referrer_path;
SELECT CASE WHEN p.is_owner=1 OR EXISTS(SELECT 1 FROM owner_clients o WHERE o.daily_client_id=p.daily_client_id) THEN 1 ELSE 0 END ownerExcluded,p.referrer_host referrerHost,COUNT(*) views,MAX(p.observed_at) lastObserved FROM page_observations p WHERE p.observed_at>='2026-10-20 00:00:00' AND p.observed_at<'2026-10-27 00:00:00' AND p.path='/privacy' AND p.reader_kind='browser' GROUP BY ownerExcluded,p.referrer_host;
